    subtema: `O céu e a terra passarão, mas as minhas palavras não passarão`,
    tema: `O Fim dos Tempos`,
    tipo: 'devocional',
    perguntaGancho: `Se vocês fossem ensinar este texto a um jovem casal, qual seria a lição principal?`,
    reflexaoTexto: `Lucas, o médico gentio, escreve para mostrar que Jesus veio buscar e salvar o perdido de toda nação e condição. O Espírito Santo permeia cada página, ungindo o Salvador e os que creem nele. Juntos, contemplem a compaixão de Jesus e deixem que ela molde o clima do lar.`,
