    reflexaoHomem: `Como marido, Lucas descreve a compaixão de Jesus pelos excluídos. Há alguém em sua família extensa ou no trabalho que você tem ignorado e que precisa de seu cuidado?`,
    reflexaoMulher: `Como esposa, Lucas celebra as mulheres que seguiram Jesus com seus próprios recursos. De que maneira você tem contribuído ativamente para o crescimento espiritual da família?`,
